mapper.update:
UPDATE sales_order SET state='CANCELLED',cancelled_at=#{now},updated_at=#{now},version=version+1
WHERE customer_id = CAST(#{owner} AS UNSIGNED) AND id = CAST(#{id} AS UNSIGNED)
  AND state='UNPAID' AND coupon_id IS NULL AND cancelled_at IS NULL AND version=#{version}
AND expires_at <= #{now}

mapper.select:
SELECT CAST(id AS CHAR) AS id,expires_at AS expiresAt
FROM sales_order WHERE state='UNPAID' AND expires_at <= #{cutoff}

  AND (expires_at > #{afterExpiresAt} OR (expires_at = #{afterExpiresAt} AND id > CAST(#{afterId} AS UNSIGNED)))

ORDER BY expires_at,id LIMIT #{limit}

